You are an expert HPC compiler optimizing C code for CPU execution
with OpenMP. Prioritize loop transformations that improve locality and
parallelism, then apply suitable OpenMP directives and clauses.

Task and scope:
- Optimize only code in regions delimited by '#pragma scope' and
  '#pragma endscop'. Preserve these marker lines unchanged.
- Preserve function signatures, program inputs/outputs, and original semantics.
- You MAY restructure loops and adjust associated C statements within the
  marked regions when needed for the priority loop transformations below.
- Do not modify code outside the marked regions. Do not add dependencies,
  data races, invalid OpenMP directives, or unsupported transformations.

HIGHEST PRIORITY — LOOP TRANSFORMATIONS (examine FIRST, in this order):
1. Loop tiling / blocking: investigate tiling of suitable nested loops to improve
   cache locality, data reuse, and parallel granularity. Choose legal tile sizes.
2. Loop fusion: investigate merging adjacent loops with compatible iteration
   spaces when no dependence makes the fused loop incorrect.
3. Loop skewing: investigate skewing loops with carried dependencies where an
   affine change can expose legal parallelism.

IMPORTANT: These three are loop transformations, not standalone OpenMP pragmas.
Do NOT falsely claim '#pragma omp' alone performs them.

SECOND PRIORITY — OPENMP DIRECTIVE-LEVEL OPTIMIZATIONS:
4. Parallelism: 'parallel for', 'for', 'collapse(n)'.
5. Scheduling: 'schedule(static|dynamic|guided|runtime)'.
6. Synchronization: 'nowait' only when safe; 'atomic'/'critical' when needed.
7. Data sharing: 'private', 'firstprivate', 'lastprivate', 'shared', 'default(none)'.
8. Reductions: 'reduction(+:x)' etc. Consider FP reassociation.
9. SIMD: 'simd', 'parallel for simd', 'simdlen(n)', 'safelen(n)', 'aligned(...)'.
10. Thread management: 'num_threads(n)', 'proc_bind(close/spread/primary)'.

Optimization decision process:
- FIRST examine tiling, fusion, and skewing, in that priority order.
- THEN examine all seven OpenMP categories, selecting only beneficial, legal choices.
- Maintain correct dependence order, variable scope, data sharing, synchronization.
- Do not change observable behavior. If no safe optimization is available, return
  the original code unchanged.
- Keep all transformations strictly within the marked scope regions.

Original code:
/**
 * This version is stamped on May 10, 2016
 *
 * Contact:
 *   Louis-Noel Pouchet <pouchet.ohio-state.edu>
 *   Tomofumi Yuki <tomofumi.yuki.fr>
 *
 * Web address: http://polybench.sourceforge.net
 */
/* correlation.c: this file is part of PolyBench/C */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "correlation.h"


/* Array initialization. */
static
void init_array (int m,
		 int n,
		 DATA_TYPE *float_n,
		 DATA_TYPE POLYBENCH_2D(data,N,M,n,m))
{
  int i, j;

  *float_n = (DATA_TYPE)N;

  for (i = 0; i < N; i++)
    for (j = 0; j < M; j++)
      data[i][j] = (DATA_TYPE)(i*j)/M + i;

}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int m,
		 DATA_TYPE POLYBENCH_2D(corr,M,M,m,m))

{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("corr");
  for (i = 0; i < m; i++)
    for (j = 0; j < m; j++) {
      if ((i * m + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
      fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, corr[i][j]);
    }
  POLYBENCH_DUMP_END("corr");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_correlation(int m, int n,
			DATA_TYPE float_n,
			DATA_TYPE POLYBENCH_2D(data,N,M,n,m),
			DATA_TYPE POLYBENCH_2D(corr,M,M,m,m),
			DATA_TYPE POLYBENCH_1D(mean,M,m),
			DATA_TYPE POLYBENCH_1D(stddev,M,m))
{
  int i, j, k;

  DATA_TYPE eps = SCALAR_VAL(0.1);


#pragma scop
  for (j = 0; j < _PB_M; j++)
    {
      mean[j] = SCALAR_VAL(0.0);
      for (i = 0; i < _PB_N; i++)
	mean[j] += data[i][j];
      mean[j] /= float_n;
    }


   for (j = 0; j < _PB_M; j++)
    {
      stddev[j] = SCALAR_VAL(0.0);
      for (i = 0; i < _PB_N; i++)
        stddev[j] += (data[i][j] - mean[j]) * (data[i][j] - mean[j]);
      stddev[j] /= float_n;
      stddev[j] = SQRT_FUN(stddev[j]);
      /* The following in an inelegant but usual way to handle
         near-zero std. dev. values, which below would cause a zero-
         divide. */
      stddev[j] = stddev[j] <= eps ? SCALAR_VAL(1.0) : stddev[j];
    }

  /* Center and reduce the column vectors. */
  for (i = 0; i < _PB_N; i++)
    for (j = 0; j < _PB_M; j++)
      {
        data[i][j] -= mean[j];
        data[i][j] /= SQRT_FUN(float_n) * stddev[j];
      }

  /* Calculate the m * m correlation matrix. */
  for (i = 0; i < _PB_M-1; i++)
    {
      corr[i][i] = SCALAR_VAL(1.0);
      for (j = i+1; j < _PB_M; j++)
        {
          corr[i][j] = SCALAR_VAL(0.0);
          for (k = 0; k < _PB_N; k++)
            corr[i][j] += (data[k][i] * data[k][j]);
          corr[j][i] = corr[i][j];
        }
    }
  corr[_PB_M-1][_PB_M-1] = SCALAR_VAL(1.0);
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int m = M;

  /* Variable declaration/allocation. */
  DATA_TYPE float_n;
  POLYBENCH_2D_ARRAY_DECL(data,DATA_TYPE,N,M,n,m);
  POLYBENCH_2D_ARRAY_DECL(corr,DATA_TYPE,M,M,m,m);
  POLYBENCH_1D_ARRAY_DECL(mean,DATA_TYPE,M,m);
  POLYBENCH_1D_ARRAY_DECL(stddev,DATA_TYPE,M,m);

  /* Initialize array(s). */
  init_array (m, n, &float_n, POLYBENCH_ARRAY(data));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_correlation (m, n, float_n,
		      POLYBENCH_ARRAY(data),
		      POLYBENCH_ARRAY(corr),
		      POLYBENCH_ARRAY(mean),
		      POLYBENCH_ARRAY(stddev));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(m, POLYBENCH_ARRAY(corr)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(data);
  POLYBENCH_FREE_ARRAY(corr);
  POLYBENCH_FREE_ARRAY(mean);
  POLYBENCH_FREE_ARRAY(stddev);

  return 0;
}


Output requirements:
Return ONLY the complete optimized C code. No explanations, Markdown code
fences, or surrounding text. Preserve the '#pragma scope' and
'#pragma endscop' markers exactly as supplied.

