  #pragma omp parallel for private(i)
  for (j = 0; j < _PB_M; j++)
    {
      double mean_j = SCALAR_VAL(0.0);
      #pragma omp simd reduction(+:mean_j)
      for (i = 0; i < _PB_N; i++)
        mean_j += data[i][j];
      mean_j = mean_j / float_n;
      mean[j] = mean_j;

      double stddev_j = SCALAR_VAL(0.0);
      #pragma omp simd reduction(+:stddev_j)
      for (i = 0; i < _PB_N; i++) {
        double diff = data[i][j] - mean_j;
        stddev_j += diff * diff;
      }
      stddev_j = stddev_j / float_n;
      stddev_j = SQRT_FUN(stddev_j);
      stddev_j = (stddev_j <= eps) ? SCALAR_VAL(1.0) : stddev_j;
      stddev[j] = stddev_j;
    }

  #pragma omp parallel for private(j)
  for (i = 0; i < _PB_N; i++) {
    #pragma omp simd
    for (j = 0; j < _PB_M; j++) {
      data[i][j] = (data[i][j] - mean[j]) / (SQRT_FUN(float_n) * stddev[j]);
    }
  }

  #pragma omp parallel for private(j, kk, k) schedule(static)
  for (i = 0; i < _PB_M-1; i++)
    {
      corr[i][i] = SCALAR_VAL(1.0);
      for (j = i+1; j < _PB_M; j++)
        {
          double temp = SCALAR_VAL(0.0);
          for (kk = 0; kk < _PB_N; kk += TILE_K)
            {
              int k_end = kk + TILE_K < _PB_N ? kk + TILE_K : _PB_N;
              #pragma omp simd reduction(+:temp)
              for (k = kk; k < k_end; k++)
                temp += data[k][i] * data[k][j];
            }
          corr[i][j] = temp;
          corr[j][i] = temp;
        }
    }
  corr[_PB_M-1][_PB_M-1] = SCALAR_VAL(1.0);
#pragma endscop
